def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] in (1, 2, 3, 6)]
    original = {(r, c) for r, c, _ in seeds}

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w and (r, c) not in original:
            out[r][c] = value

    # Color 1: short rightward stroke with a raised endpoint.
    for r, c, color in seeds:
        if color == 1:
            put(r, c + 1, 5)
            put(r, c + 2, 5)
            put(r - 1, c + 2, 1)
        elif color == 2:
            # Four cells left, with a matching 2 at the far end.
            for k in range(1, 5):
                put(r, c - k, 2 if k == 4 else 5)
        elif color == 3:
            put(r + 1, c, 5)
            put(r + 2, c, 5)
            put(r + 3, c, 3)
        elif color == 6:
            # Vertical ray upward, capped by 6 at the top; diagonal is added from crossings below.
            for rr in range(r):
                put(rr, c, 6 if rr == 0 else 5)

    # The 2 stroke crossing a vertical 3/6 stroke produces a 4 and a down-left 4 ray.
    two_rows = {r for r, c, color in seeds if color == 2}
    vertical_cols = set()
    for r, c, color in seeds:
        if color == 3:
            vertical_cols.add(c)  # downward extension
        elif color == 6:
            vertical_cols.add(c)  # upward extension
    for r in two_rows:
        for c in vertical_cols:
            if 0 <= c < w and out[r][c] != 0 and (r, c) not in original:
                out[r][c] = 4
                for k in range(1, min(h - r, c + 1)):
                    put(r + k, c - k, 4)

    return out
