def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] in (1, 2, 3, 6)]
    original = {(r, c) for r, c, _ in seeds}

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w and (r, c) not in original:
            out[r][c] = value

    for r, c, color in seeds:
        if color == 1:
            put(r, c + 1, 5); put(r, c + 2, 5); put(r - 1, c + 2, 1)
        elif color == 2:
            for k in range(1, 5):
                put(r, c - k, 2 if k == 4 else 5)
        elif color == 3:
            put(r + 1, c, 5); put(r + 2, c, 5); put(r + 3, c, 3)
        elif color == 6:
            # Full column, with 6 at both ends and 5 between.
            for rr in range(h):
                if rr != r:
                    put(rr, c, 6 if rr == 0 else 5)

    # Where a color-2 horizontal trace intersects a color-6 vertical trace,
    # the crossing becomes 4 and emits a diagonal ray down-left.
    two_rows = {r for r, c, color in seeds if color == 2}
    six_cols = {c for r, c, color in seeds if color == 6}
    for r in two_rows:
        for c in six_cols:
            if 0 <= c < w and (r, c) not in original:
                out[r][c] = 4
                for k in range(1, min(h-r, c+1)):
                    put(r+k, c-k, 4)

    return out
